  if (Number.isFinite(p1) && p1 > 10000) { usdtToman = Math.round(p1); fxSource = 'wallex_live'; }
  else if (Number.isFinite(p2) && p2 > 10000) { usdtToman = Math.round(p2); fxSource = wallex?.source || 'mcp_proxy'; }
